class All(Expr):
    """A compiled lexical quantifier, whose body is built just once."""
    def __init__(self, binding, array_expr, body):
        self.type = Bool()
        self.binding = binding
        self.array_expr = array_expr
        self.body = body


class TypeRegistry:
    """Resolve forward references once, preserving named declarations and sharing."""
    def __init__(self, definitions):
        self.definitions = {item["name"]: item for item in definitions}
        self.types = {}

    def __getitem__(self, name):
        if name in self.types:
            return self.types[name]
        item = self.definitions[name]
        kind = item["kind"]
        if kind == "bool":
            result = Bool()
        elif kind == "char":
            result = Char()
        elif kind == "int":
            result = Int(item["bits"])
        elif kind == "string":
            result = String(item["maxsize"])
        elif kind == "enum":
            result = Enum(name, item["values"])
        elif kind == "array":
            result = Array(self[item["element"]], item["size"])
        elif kind == "struct":
            result = Struct(name)
            result.fields = {field: self[child] for field, child in item["fields"]}
        elif kind == "alias":
            result = Alias(name, self[item["target"]])
        elif kind == "void":
            result = Void()
        else:
            raise ValueError("unknown type")
        self.types[name] = result
        return result


class ExpressionCompiler:
    """Compile the protocol expression arrays against a lexical type scope."""
    OPERATORS = {"eq": "==", "ne": "!=", "lt": "<", "le": "<=",
                 "gt": ">", "ge": ">=", "add": "+", "sub": "-",
                 "and": "&", "or": "|", "implies": "implies"}

    def __init__(self, registry):
        self.registry = registry

    def compile(self, source, scope):
        if source is None:
            return Const(Bool(), True)
        op = source[0]
        if op == "var":
            return Var(Type.inner(scope[source[1]]), source[1])
        if op == "const":
            # Constants, including nested strings, are already JSON values.
            # In particular, never apply C-string recovery to constants.
            return Const(Type.inner(self.registry[source[1]]), source[2])
        if op == "field":
            expr = self.compile(source[1], scope)
            return Field(Type.inner(Type.inner(expr.type).fields[source[2]]), expr, source[2])
        if op == "index":
            return Index(self.compile(source[1], scope), source[2])
        if op == "all":
            array = self.compile(source[2], scope)
            inner_scope = scope.copy()
            inner_scope[source[1]] = Type.inner(array.type).element_type
            body = self.compile(source[3], inner_scope)
            return All(source[1], array, body)
        if op == "not":
            return Not(Bool(), self.compile(source[1], scope))
        if op == "match":
            return Match(Bool(), self.compile(source[1], scope), re.parse(source[2]))
        left = self.compile(source[1], scope)
        right = self.compile(source[2], scope)
        result_type = left.type if op in ("add", "sub") else Bool()
        return Binop(result_type, self.OPERATORS[op], left, right)

    def visit_Int(self, node):
        from eywa.wire import InvalidTest
        value = self._lookup(integer_width(node.size))
        if value >= (1 << node.size):
            raise InvalidTest("integer padding")
        return value

    def visit_String(self, node):
        self._next()
        # Consume and validate even the bytes after the first NUL.
        chars = [self.visit_Char(node.char_type) for _ in range(node.maxsize)]
        return "".join(chars).split("\0", 1)[0]

    def visit_Enum(self, node):
        from eywa.wire import InvalidTest
        value = self._lookup(4)
        if value >= len(node.values):
            raise InvalidTest("enum range")
        return node.values[value]

    def visit_Array(self, node):
        self._next()
        return [self.visit(node.element_type) for _ in range(node.maxsize)]

    def visit_Struct(self, node):
        self._next()
        return {field: self.visit(child) for field, child in node.fields.items()}

    def visit_Alias(self, node):
        return self.visit(node.type)


class RegexModule(Function):
    """_summary_
    A module that checks for regex matches.
    """
    def __init__(self, name: str, regex_str: str, input: Parameter):
        self.name = name
        self.inputs = [input]
        self.regex_str = regex_str
        self.precondition = None
        self.description = f'Module that checks if the input matches the regex: {regex_str}'
        self.regex = self.get_regex()
        self.result = Parameter(name="result", type=Bool(), description="True if the input matches the regex, False otherwise")

    @staticmethod
    def regex_parser(regex):
        return re.parse(regex)

    def get_regex(self) -> re.Regex:
        regex = self.regex_str
        return self.regex_parser(regex)


